<?php
declare(strict_types=1);
// Round-trip the generated 5,000-book organisation fixture; requires its completed Undo.
define('OC_CONSOLE',true);require '/var/www/html/lib/base.php';
if(getenv('LIBRARY_DISPOSABLE_FIXTURE')!=='1')throw new RuntimeException('Disposable fixture opt-in required');
set_exception_handler(static function(Throwable $e):void{fwrite(STDERR,get_class($e).': '.$e->getMessage()."\n".$e->getTraceAsString()."\n");exit(1);});
function service(string $name):object{return \OC::$server->get('OCA\\Library\\Service\\'.$name);}
function check(bool $ok,string $message):void{if(!$ok)throw new RuntimeException($message);echo "PASS $message\n";}
$fixture=json_decode(file_get_contents('/tmp/library-curation-bulk.json'),true,32,JSON_THROW_ON_ERROR);$uid=$fixture['uid'];if(!str_starts_with($uid,'library-bulk-boundary-'))throw new RuntimeException('Invalid fixture owner');
\OC::$server->get(\OCP\IUserSession::class)->setUser(\OC::$server->get(\OCP\IUserManager::class)->get($uid));$db=\OC::$server->get(\OCP\IDBConnection::class);$archives=service('CurationPortabilityService');check(service('CurationJobService')->show($uid,$fixture['job'])['status']==='undone','organisation fixture has completed Undo');
function checksum():string{global $db,$uid;$r=$db->executeQuery('SELECT id,title,publisher,description,workflow_status,starred FROM *PREFIX*library_items WHERE user_id=? ORDER BY id',[$uid]);$hash=hash_init('sha256');while($row=$r->fetch())hash_update($hash,json_encode($row,JSON_THROW_ON_ERROR));$r->closeCursor();return hash_final($hash);}
function settle(string $id,string $state):array{global $archives,$uid;$start=microtime(true);$steps=0;for(;$steps<40000;$steps++){if($steps%100===0 && $archives->show($uid,$id)['status']!==$state)break;$archives->advance();} $job=$archives->show($uid,$id);echo json_encode(['phase'=>$state,'workerMs'=>round((microtime(true)-$start)*1000,1),'steps'=>$steps,'status'=>$job['status'],'phpPeakBytes'=>memory_get_peak_usage(true)]),"\n";return $job;}
foreach(['AuthorStorageService','SeriesStorageService'] as $storage){for($n=0;$n<100 && service($storage)->status($uid)['pending']>0;$n++)service($storage)->advance($uid,500,30);$status=service($storage)->status($uid);check($status['pending']===0 && $status['failed']===0,'all archive relationships finish indexing');}
$before=checksum();$export=$archives->create($uid,'export');check(settle($export['id'],'exporting')['status']==='complete','large curation export completes');$path='/tmp/library-curation-scale.jsonl';$out=fopen($path,'wb');foreach($archives->download($uid,$export['id']) as $line)fwrite($out,$line);fclose($out);$bytes=filesize($path);check($bytes<1073741824,'framed archive remains within its documented file limit');
$in=fopen($path,'rb');$manifest=json_decode(fgets($in),true,32,JSON_THROW_ON_ERROR);$restore=$archives->create($uid,'restore');$batch=[];$uploaded=0;$times=[];$duplicates=false;
$flush=function()use(&$batch,&$uploaded,&$times,&$duplicates,$archives,$uid,$restore):void{if(!$batch)return;$start=microtime(true);$first=$archives->upload($uid,$restore['id'],$batch);$times[]=(microtime(true)-$start)*1000;if(!$duplicates){$retry=$archives->upload($uid,$restore['id'],$batch);check($retry['bytes']===$first['bytes'],'large upload retry does not duplicate records or bytes');$duplicates=true;}$uploaded+=count($batch);$batch=[];};
while(($line=fgets($in))!==false){$batch[]=json_decode($line,true,64,JSON_THROW_ON_ERROR);if(count($batch)===20)$flush();}$flush();fclose($in);check($uploaded===$manifest['records'],'large streamed upload preserves the manifest count');$archives->control($uid,$restore['id'],'finish',$uploaded);$review=settle($restore['id'],'validating');check($review['status']==='review','large archive reaches review');check(array_sum(array_map(fn($row)=>$row['status']==='conflict' ? (int)$row['n'] : 0,$review['counts']))===0,'large fixture has no review conflicts');
$archives->control($uid,$restore['id'],'approve');$result=settle($restore['id'],'applying');check($result['status']==='complete','large archive restore completes');check(array_sum(array_map(fn($row)=>$row['status']==='applied' ? (int)$row['n'] : 0,$result['counts']))===$uploaded,'all archive records apply once');check(checksum()===$before,'large round trip preserves visible saved book values');check((int)$db->executeQuery('SELECT COUNT(*) FROM *PREFIX*library_items WHERE user_id=?',[$uid])->fetchOne()===5000,'large restore retains the catalogue count');
$files=\OC::$server->get(\OCP\Files\IRootFolder::class)->getUserFolder($uid)->get('Boundary books');$expected=hash_file('sha256','/tmp/library-fixture.pdf');$count=0;foreach($files->getDirectoryListing() as $file){if(!$file instanceof \OCP\Files\File)continue;check(hash('sha256',$file->getContent())===$expected,'restored source bytes unchanged');$count++;}check($count===5000,'all five thousand source files are preserved');
sort($times);echo json_encode(['records'=>$uploaded,'archiveBytes'=>$bytes,'uploadBatches'=>count($times),'uploadMedianMs'=>round($times[intdiv(count($times),2)],2),'uploadMaxMs'=>round(max($times),2),'phpPeakBytes'=>memory_get_peak_usage(true)]),"\n";
$archives->control($uid,$export['id'],'delete');$archives->control($uid,$restore['id'],'delete');for($n=0;$n<500;$n++){$archives->expire();if(!(int)$db->executeQuery('SELECT COUNT(*) FROM *PREFIX*library_portable_jobs WHERE user_id=?',[$uid])->fetchOne())break;}check((int)$db->executeQuery('SELECT COUNT(*) FROM *PREFIX*library_portable_jobs WHERE user_id=?',[$uid])->fetchOne()===0,'large archive cleanup completes in bounded passes');unlink($path);
